"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16269"],{75524(e){e.exports=JSON.parse('{"id":"FIN-1030","slug":"intercompany-transaction","term":"Intercompany Transaction","also_known_as":[],"difficulty":"Advanced","definition":"An intercompany transaction is a transaction between two companies in the same group, such as a sale of goods, a loan, a service charge or a dividend between a parent and its subsidiary.","explanation":["Groups often trade within themselves. A manufacturing subsidiary may sell products to a sales subsidiary in another country, a parent may lend money to a subsidiary, or a central services company may charge other group companies for IT and finance support.","In the separate accounts of each company, these transactions are recorded like any other. But in the consolidated accounts, which present the group as a single business, they must be removed, because a group cannot make a sale to itself or owe money to itself.","For example, if one subsidiary sells goods to another for 500,000, the group\'s consolidated revenue and costs must both be reduced by 500,000, and any profit still sitting in unsold inventory must be removed.","Intercompany transactions require careful tracking and matching between group companies, which can be a major task during the financial close. Across borders, their prices also determine where profits are taxed, so they must follow transfer pricing rules."],"note":"","total":1725,"prev":{"slug":"interchange-fee","term":"Interchange Fee"},"next":{"slug":"interest","term":"Interest"}}')}}]);